import re
_WORD = re.compile(r'[a-z0-9]+')
def overlap(first, second):
    a=_WORD.findall(first.lower()); b=_WORD.findall(second.lower())
    prev=list(range(len(b)+1))
    for i,t in enumerate(a,1):
        cur=[i]
        for j,o in enumerate(b,1):
            cur.append(min(prev[j]+1, cur[j-1]+1, prev[j-1]+(t!=o)))
        prev=cur
    return 1.0-prev[-1]/max(len(a),len(b))
pairs = {
 'worked': ("A compact, validator-safe decision-tree flowchart and a breakdown of why it satisfies the packet validator's label, connector, and width checks. This is overflow detail; `../../SKILL.md` is the authoritative workflow contract.",
            "Gives a failing tree something to compare against, property by property."),
 'catalog': ("Each row turns one reader question into one type and one example, so the choice is made in one pass.",
             "The table between the sentinels below is machine-read: the corpus check matches its columns by header name rather than by position."),
 'derivation': ("Where every diagram-skin color comes from, and what stays fixed when the skin changes.",
                "Classifies every diagram-skin value as hand-picked, derived or fixed, and records the rule or source behind it."),
 'router': ("The whole router in one piece, so a route can be followed from a request to the files it loads without leaving the page.",
